import java.util.*;
public class TestMain{static void eq(Object a,Object b){if(!Objects.equals(a,b))throw new AssertionError(a+" != "+b);}public static void main(String[]a){List<Item>items=new ArrayList<>(List.of(new Item("b",10),new Item("a",10),new Item("x:id",9),new Item("z",8)));Page p1=Paginator.page(items,null,2);eq(p1.items(),List.of(new Item("a",10),new Item("b",10)));Page p2=Paginator.page(items,p1.nextCursor(),2);eq(p2.items(),List.of(new Item("x:id",9),new Item("z",8)));eq(p2.nextCursor(),null);items.add(new Item("new",99));Page stable=Paginator.page(items,p1.nextCursor(),2);eq(stable.items(),p2.items());try{p1.items().add(new Item("q",1));throw new AssertionError();}catch(UnsupportedOperationException e){}try{Paginator.page(items,"bad",2);throw new AssertionError();}catch(IllegalArgumentException e){}try{Paginator.page(items,null,0);throw new AssertionError();}catch(IllegalArgumentException e){}System.out.println("OK");}}
